#!/usr/bin/env python3
import base64,zlib,json,subprocess,pathlib,re
from concurrent.futures import ThreadPoolExecutor,as_completed
B64=''
TRACKS=json.loads(zlib.decompress(base64.b64decode(B64)).decode())
ROOT=pathlib.Path(__file__).resolve().parents[2]; HTML=ROOT/'youtube-playlist-player/app/src/main/assets/index.html'
def resolve(item):
 q=item['artist']+' '+item['title']
 for x in (q+' official',q):
  try:
   p=subprocess.run(['yt-dlp','--flat-playlist','--skip-download','--playlist-end','1','--print','%(id)s\t%(title)s','ytsearch1:'+x],capture_output=True,text=True,timeout=20)
   line=next((s.strip() for s in p.stdout.splitlines() if s.strip()),'')
   if line:
    parts=line.split('\t',1); vid=parts[0].strip(); title=parts[1].strip() if len(parts)>1 else ''
    if re.fullmatch(r'[A-Za-z0-9_-]{11}',vid): return vid,title
  except Exception: pass
 return None,None
flat=[(k,i,x) for k,v in TRACKS.items() for i,x in enumerate(v)]; results={k:[None]*len(v) for k,v in TRACKS.items()}; ok=0
with ThreadPoolExecutor(max_workers=10) as ex:
 fm={ex.submit(resolve,x):(k,i,x) for k,i,x in flat}
 for f in as_completed(fm):
  k,i,x=fm[f]
  try: vid,found=f.result()
  except Exception: vid,found=None,None
  ok+=bool(vid); results[k][i]={'id':vid,'url':'https://www.youtube.com/watch?v='+vid if vid else None,'label':x['title'],'artist':x['artist'],'resolvedTitle':found}
  print(f'[{k} {i+1:03d}/{len(TRACKS[k])}] '+(('OK '+vid) if vid else 'NON RESOLU')+' - '+x['artist']+' - '+x['title'],flush=True)
payload=json.dumps(results,ensure_ascii=False,separators=(',',':'))
runtime='''<script id="pme-wedding-playlists-v1">\n(function(){\nconst W=__PAYLOAD__;DEFAULT_PLAYLISTS.wedding=W.wedding;DEFAULT_PLAYLISTS.wedding_qc=W.wedding_qc;\nwindow.refreshSaved=function(){const s=$("savedSelect"),d=saved(),c=s.value;s.innerHTML='<option value="">Choisir une playlist…</option>';[["default:global","🌎 Sélection originale",DEFAULT_PLAYLISTS.global],["default:quebec","⚜️ Québec 2000–2026",DEFAULT_PLAYLISTS.quebec],["default:wedding","💍 Mariage — Top 100",DEFAULT_PLAYLISTS.wedding],["default:wedding_qc","⚜️💍 Mariage québécois — 20 titres",DEFAULT_PLAYLISTS.wedding_qc]].forEach(([v,n,l])=>{const o=document.createElement("option");o.value=v;o.textContent=n+" ("+l.length+")";s.appendChild(o)});Object.keys(d).sort().forEach(k=>{const o=document.createElement("option");o.value="user:"+k;o.textContent="💾 "+k+" ("+d[k].length+")";s.appendChild(o)});if([...s.options].some(o=>o.value===c))s.value=c};\nwindow.loadSelected=function(){const v=$("savedSelect").value,d=saved();if(!v)return;const defs={"default:global":["Sélection originale",DEFAULT_PLAYLISTS.global],"default:quebec":["Québec 2000–2026",DEFAULT_PLAYLISTS.quebec],"default:wedding":["Mariage — Top 100",DEFAULT_PLAYLISTS.wedding],"default:wedding_qc":["Mariage québécois — 20 titres",DEFAULT_PLAYLISTS.wedding_qc]};if(defs[v]){tracks=JSON.parse(JSON.stringify(defs[v][1]));$("playlistName").value=defs[v][0]}else if(v.startsWith("user:")){const n=v.slice(5);if(!d[n])return;tracks=JSON.parse(JSON.stringify(d[n]));$("playlistName").value=n}else return;index=0;render();if(ready&&tracks.length)loadCurrent(false)};\nrefreshSaved();\n})();\n</script>'''.replace('__PAYLOAD__',payload)
s=HTML.read_text(encoding='utf-8');s=re.sub(r'\n?<script id="pme-wedding-playlists-v1">.*?</script>\s*','\n',s,flags=re.S);s=s.replace('</body>',runtime+'\n</body>');HTML.write_text(s,encoding='utf-8')
print(f'Playlists mariage résolues: {ok}/{len(flat)}',flush=True)
if ok<110: raise SystemExit(f'Trop peu de titres mariage résolus: {ok}/{len(flat)}')
